 1→#!/usr/bin/env node
 2→/**
 3→ * concordance-sync.js — Extracts debate data from source files into JSON
 4→ *
 5→ * Usage:
 6→ *   node www/concordance-sync.js
 7→ *
 8→ * Reads from:
 9→ *   18.313x/*.md                    (QA and summary debate files)
10→ *   18.313x/DEBATE_STATE.md         (accumulated markers)
11→ *   18.313x/debate_log.jsonl        (structured event log)
12→ *   content/Papers/Nature_PeqNP/v3/DEBATE_CONCORDANCE.md  (enriched concordance)
13→ *
14→ * Writes to:
15→ *   www/data/concordance-data.js    (loadable by the HTML app)
16→ */
17→
18→const fs = require('fs');
19→const path = require('path');
20→
21→const ROOT = path.resolve(__dirname, '..');
22→const SOURCE_DIR = path.join(ROOT, '18.313x');
23→const CONCORDANCE_MD = path.join(ROOT, 'content', 'Papers', 'Nature_PeqNP', 'v3', 'DEBATE_CONCORDANCE.md');
24→const OUTPUT_DIR = path.join(__dirname, 'data');
25→const OUTPUT_FILE = path.join(OUTPUT_DIR, 'concordance-data.js');
26→
27→// --- Parsers ---
