#!/usr/bin/env node
/**
 * concordance-sync.js — Extracts debate data from source files into JSON
 *
 * Usage:
 *   node www/concordance-sync.js
 *
 * Reads from:
 *   18.313x/*.md                    (QA and summary debate files)
 *   18.313x/DEBATE_STATE.md         (accumulated markers)
 *   18.313x/debate_log.jsonl        (structured event log)
 *   content/Papers/Nature_PeqNP/v3/DEBATE_CONCORDANCE.md  (enriched concordance)
 *
 * Writes to:
 *   www/data/concordance-data.js    (loadable by the HTML app)
 */

const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const SOURCE_DIR = path.join(ROOT, '18.313x');
const CONCORDANCE_MD = path.join(ROOT, 'content', 'Papers', 'Nature_PeqNP', 'v3', 'DEBATE_CONCORDANCE.md');
const OUTPUT_DIR = path.join(__dirname, 'data');
const OUTPUT_FILE = path.join(OUTPUT_DIR, 'concordance-data.js');

// --- Parsers ---

/** Parse a QA-format file (## Context / ## Question / ## Answer / ## Commentary) */
function parseQAFile(filepath, exchangeNum) {
  const content = fs.readFileSync(filepath, 'utf-8');
  const lines = content.split('\n');

  let title = '';
  const titleMatch = lines[0]?.match(/^#\s+.*?—\s+Exchange\s+\d+/i);
  if (titleMatch) {
    title = lines[0].replace(/^#\s+/, '').trim();
  }

  // Find known ## sections by position (ignore subsections within answers)
  const knownSections = ['question', 'answer', 'context', 'commentary', 'moderator', 'narrator'];
  const sections = [];
  for (let i = 0; i < lines.length; i++) {
    const match = lines[i].match(/^##\s+(.+)/);
    if (match) {
      const name = match[1].trim().toLowerCase();
      if (knownSections.some(k => name.startsWith(k))) {
        sections.push({ name, start: i + 1 });
      }
    }
  }

  // Extract text between sections
  function getSection(name) {
    const idx = sections.findIndex(s => s.name.startsWith(name));
    if (idx < 0) return null;
    const start = sections[idx].start;
    const end = idx + 1 < sections.length ? sections[idx + 1].start - 1 : lines.length;
    return lines.slice(start, end).join('\n').trim();
  }

  const context = getSection('context');
  const question = getSection('question');
  const answer = getSection('answer');
  const commentary = getSection('commentary') || getSection('moderator') || getSection('narrator');

  // Detect if answer is a stub (just an opening line)
  const answerIsStub = answer && answer.split('\n').filter(l => l.trim()).length <= 2;

  const turns = [];
