    turns.push({ speaker: 'moderator', role: 'Moderator (@pnp-moderator)', section: 'Context', text: context });
  }
  if (question) {
    turns.push({ speaker: 'essam', role: 'Stan/Ulam', text: question });
  }
  if (answer) {
    turns.push({ speaker: 'godel', role: 'AI Gödel (@pnp-godel)', text: answer, isStub: answerIsStub });
  }
  if (commentary) {

