      if (inQuote && currentQuote.length > 0) {
        turns.push(inferTurn(currentSection, currentQuote.join('\n')));
        currentQuote = [];
        inQuote = false;
      }
      currentSection = line.replace(/^###\s+/, '').trim();
      continue;
    }

    // Collect block quotes
    if (line.startsWith('>')) {
      inQuote = true;
      currentQuote.push(line.replace(/^>\s?/, ''));
    } else if (inQuote && line.trim() === '') {
      // End of quote block
      if (currentQuote.length > 0) {
        turns.push(inferTurn(currentSection, currentQuote.join('\n')));
        currentQuote = [];
      }
      inQuote = false;
    }
  }
  // Flush final quote
  if (currentQuote.length > 0) {
    turns.push(inferTurn(currentSection, currentQuote.join('\n')));
  }

  // Also capture full section text for non-quote narrative
  const sections = extractSections(content);

  return {
    exchangeNum,
    sourceFile: path.basename(filepath),
    sourceFormat: 'summary',
    title,
    turns: turns.length > 1 ? turns : extractNarrativeTurns(content),
    sections
  };
}

