/** Infer speaker from section name */
function inferTurn(section, text) {
  const s = section.toLowerCase();
  if (s.includes('stan') || s.includes('essam') || s.includes('challenge') || s.includes('direction'))
    return { speaker: 'essam', role: 'Stan/Ulam', section, text };
  if (s.includes('gödel') || s.includes('godel') || s.includes('skeptic') || s.includes('concession') || s.includes('revised'))
    return { speaker: 'godel', role: 'AI Gödel (@pnp-godel)', section, text };
  if (s.includes('von neumann') || s.includes('vn') || s.includes('jvm') || s.includes('advocate'))
    return { speaker: 'von_neumann', role: 'AI von Neumann (@pnp-jvm)', section, text };
  if (s.includes('rota') || s.includes('entropy advisor'))
    return { speaker: 'rota', role: 'AI Rota (@pnp-rota)', section, text };
  // Content-based inference for narrative sections
  if (s.includes('argument') || s.includes('frontier') || s.includes('resolution') || s.includes('implementation'))
    return { speaker: 'narrator', role: 'Context', section, text };
  if (s.includes('objection') || s.includes('contention') || s.includes('#p'))
    return { speaker: 'godel', role: 'AI Gödel (@pnp-godel)', section, text };
  if (s.includes('rect') || s.includes('readhead'))
    return { speaker: 'von_neumann', role: 'AI von Neumann (@pnp-jvm)', section, text };
  return { speaker: 'narrator', role: 'Context', section, text };
}

/** Extract named sections from markdown */
function extractSections(content) {
  const sections = {};
  const parts = content.split(/^##\s+/m);
  for (const part of parts) {
    if (!part.trim()) continue;
    const firstNewline = part.indexOf('\n');
    const name = part.substring(0, firstNewline).trim();
    const body = part.substring(firstNewline).trim();
    sections[name] = body;
  }
  return sections;
}

/** Convert sections to turns (fallback for files without block quotes) */
function sectionsToTurns(sections) {
  const turns = [];
  for (const [name, body] of Object.entries(sections)) {
    if (body.length > 50) {
      turns.push(inferTurn(name, body));
    }
  }
  return turns;
}

/** Enhanced summary parser: also extract subsections as separate turns */
function extractNarrativeTurns(content) {
  const turns = [];
  const sections = content.split(/^##\s+/m).filter(s => s.trim());

  for (const section of sections) {
    const firstNl = section.indexOf('\n');
    const sectionName = section.substring(0, firstNl).trim();
    const sectionBody = section.substring(firstNl).trim();

    // Check if section has subsections with speaker-identifiable headers
    const subsections = sectionBody.split(/^###\s+/m);

    if (subsections.length > 1) {
      // First part is section intro
      if (subsections[0].trim().length > 50) {
        turns.push(inferTurn(sectionName, subsections[0].trim()));
      }
      // Subsections are individual contributions
      for (let i = 1; i < subsections.length; i++) {
        const subNl = subsections[i].indexOf('\n');
        const subName = subsections[i].substring(0, subNl).trim();
        const subBody = subsections[i].substring(subNl).trim();
        if (subBody.length > 30) {
          turns.push(inferTurn(subName, subBody));
        }
      }
    } else if (sectionBody.length > 50) {
      turns.push(inferTurn(sectionName, sectionBody));
    }
  }

  return turns;
}

/** Parse DEBATE_STATE.md for markers */
function parseDebateState(filepath) {
  if (!fs.existsSync(filepath)) return { consensus: [], concessions: [], insights: [], failures: [] };
  const content = fs.readFileSync(filepath, 'utf-8');

  const consensus = [];
  const concessions = [];
  const failures = [];

  // Parse consensus table rows
  const cMatches = content.matchAll(/\|\s*(C\d+)\s*\|([^|]+)\|([^|]+)\|/g);
  for (const m of cMatches) {
    consensus.push({ id: m[1].trim(), text: m[2].trim(), exchange: m[3].trim() });
  }

  // Parse concession table rows
  const yMatches = content.matchAll(/\|\s*(Y\d+)\s*\|([^|]+)\|([^|]+)\|([^|]+)\|/g);
  for (const m of yMatches) {
    concessions.push({ id: m[1].trim(), who: m[2].trim(), text: m[3].trim(), exchange: m[4].trim() });

